"""
CONSISTENTIE-FIX: dezelfde yf.download() -> Ticker().history()-overstap
(die eerder al dashboard.py's live portfolio-data fixte) ook toegepast op
de dagelijkse/wekelijkse batch-scripts die Momentocrats/Snowballers/
Rocket List voeden.

Op je verzoek: hoewel de impact hier klein is (deze signalen kijken naar
meerdaagse/wekelijkse trendpatronen, niet dag-op-dag-vergelijkingen, dus
een 1-dag-achterstand in de laatste candle heeft weinig effect op de
uitkomst), is dezelfde, bevestigd betrouwbaardere methode nu ook hier
toegepast, voor consistentie door de hele codebase heen.

Bijgewerkt:
1. screener_daily.py's fetch_daily(): yf.download() -> Ticker().history()
2. screener.py's fetch_weekly(): yf.download() -> Ticker().history()

Beide functies hadden al een MultiIndex-kolom-check (voor het geval
yfinance toch een MultiIndex teruggeeft) -- die blijft gewoon staan als
extra vangnet, ook al triggert die nu vrijwel nooit meer (Ticker().
history() geeft voor 1 ticker geen MultiIndex terug).

Grondig getest: beide functies met de EXACTE kolomstructuur die Ticker().
history() teruggeeft (inclusief de extra Dividends/Stock Splits-kolommen
die yf.download() niet had) -- bevestigd dat de bestaande kolom-selectie
dit correct blijft afhandelen, en dat fetch_weekly's resample_to_weekly-
aanroep ook correct blijft werken.

Gebruik: python fix_batch_scripts_yfinance_consistency.py
Draai dit vanuit je stock_screener-map (hestys-fresh).
"""
SCREENER_CONTENT = b'"""\nSignalen-screener (GEEN geautomatiseerde strategie): checkt een lijst\naandelen op een RECENTE bullish Supertrend-omslag op de weekly timeframe,\nzodat jij zelf -- met je eigen verdere analyse -- kan beslissen of je\nlong wil gaan.\n\nVolledig zelfstandig project, los van de crypto-bot-codebase.\n\nStandaard wordt de samenstelling van AEX + Nasdaq-100 (QQQ) automatisch\nopgehaald van Wikipedia. Wil je een eigen vaste lijst (bv. je DEGIRO-\nwatchlist)? Zet TICKERS hieronder op een lijst i.p.v. None.\n\nVereist: pip install -r requirements.txt\n\nGebruik: python screener.py\n"""\nfrom __future__ import annotations\n\nimport io\n\nimport pandas as pd\nimport requests\nimport yfinance as yf\n\nfrom indicators import supertrend, ema, resample_to_weekly, volume_ratio\nfrom emailer import send_email, is_configured as email_is_configured\n\n# Wikipedia blokkeert verzoeken zonder een \'normale\' browser-User-Agent (403 Forbidden)\n_HEADERS = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"}\n\n\ndef _fetch_wikipedia_tables(url: str):\n    response = requests.get(url, headers=_HEADERS, timeout=15)\n    response.raise_for_status()\n    # StringIO nodig omdat pd.read_html een kale string anders soms als\n    # bestandsnaam/URL probeert te interpreteren i.p.v. als ruwe HTML-inhoud\n    return pd.read_html(io.StringIO(response.text))\n\n# --- Pas dit aan naar jouw eigen watchlist, of laat op None voor AEX + Nasdaq-100 ---\nTICKERS = None\n\nFALLBACK_TICKERS = [\n    "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "JPM", "V", "UNH",\n    "ASML.AS", "ADYEN.AS", "SHELL.AS", "INGA.AS", "HEIA.AS",\n    "SAP.DE", "SIE.DE", "MC.PA", "OR.PA",\n]\n\n# --- Instellingen (pas gerust aan om te \'tweaken\') ---\nATR_LENGTH = 6\nATR_MULTIPLIER = 2.6\nLOOKBACK_WEEKS_FOR_SIGNAL = 2\nTREND_FILTER_EMA_LENGTH = 20\nYEARS_OF_HISTORY = 3\nBENCHMARK_LOOKBACK_WEEKS = 12\nVOLUME_AVG_WEEKS = 20  # periode voor het gemiddelde volume, voor de volume-bevestiging\nMIN_PRIOR_TREND_WEEKS = 8  # de voorgaande (bearish) periode moet minstens dit lang zijn geweest --\n                            # filtert zigzag-ruis binnen een al lopende trend eruit\nEARNINGS_RELEVANCE_WEEKS = 8  # een winst-verrassing telt alleen nog mee in de score als\n                               # de cijfers niet ouder zijn dan dit -- daarna is het al \'verwerkt\'  # periode waarover relatieve sterkte t.o.v. de index wordt vergeleken\n\nBENCHMARKS = {".AS": "^AEX", ".DE": "^GDAXI", ".PA": "^FCHI"}  # index-suffix -> bijbehorende benchmark\nDEFAULT_BENCHMARK = "^GSPC"  # al het overige (VS) -> S&P 500\n\n\ndef get_benchmark_for_ticker(ticker: str) -> str:\n    for suffix, benchmark in BENCHMARKS.items():\n        if ticker.endswith(suffix):\n            return benchmark\n    return DEFAULT_BENCHMARK\n\n\ndef get_trailing_return_pct(df: pd.DataFrame, weeks: int):\n    """Rendement van de laatste \'weeks\' weken, of None als er te weinig geschiedenis is."""\n    if len(df) <= weeks:\n        return None\n    price_then = df["close"].iloc[-(weeks + 1)]\n    price_now = df["close"].iloc[-1]\n    return (price_now / price_then - 1) * 100\n\n\ndef fetch_benchmark_returns() -> dict:\n    """Haalt voor elke benchmark-index 1x het trailing-rendement op."""\n    returns = {}\n    for benchmark_ticker in set(list(BENCHMARKS.values()) + [DEFAULT_BENCHMARK]):\n        try:\n            df_bench = fetch_weekly(benchmark_ticker)\n            returns[benchmark_ticker] = get_trailing_return_pct(df_bench, BENCHMARK_LOOKBACK_WEEKS)\n        except Exception as exc:\n            print(f"Kon benchmark {benchmark_ticker} niet ophalen: {exc}")\n            returns[benchmark_ticker] = None\n    return returns\n\n\ndef compute_score(result: dict) -> float:\n    """\n    Score op een vaste schaal van 0 tot 10 -- GEEN geoptimaliseerde/\n    gebacktestte formule, puur een gewogen, BEGRENSDE optelsom om je\n    aandacht te sturen naar signalen die op meerdere vlakken sterk zijn.\n\n    Opbouw (max. punten per onderdeel, totaal = 10):\n    - Versheid van de omslag:              max 1,5 punten\n    - ROIC-niveau + -trend:                max 1,5 punten\n    - Relatieve sterkte vs. index:         max 2,5 punten\n    - Volume-bevestiging:                  max 1,0 punt\n    - Winst-verrassing (indien recent):    max 1,5 punten\n    - Afwijking t.o.v. analisten-koersdoel: max 2,0 punten\n    Bij ontbrekende data telt een onderdeel neutraal (de helft van het max.).\n    """\n    # --- Versheid (0-1,5 punten) ---\n    freshness_score = max(0.0, (LOOKBACK_WEEKS_FOR_SIGNAL - result["weken_geleden"]) / LOOKBACK_WEEKS_FOR_SIGNAL * 1.5)\n\n    # --- ROIC (0-1,5 punten): niveau (verzadigt bij 30%) + trend-bonus/malus ---\n    if result["roic_pct"] is not None:\n        level_points = min(max(result["roic_pct"], 0), 30) / 30 * 1.0\n        trend_points = 0.5 if result["roic_trend"] == "stijgend" else (-0.5 if result["roic_trend"] == "dalend" else 0)\n        roic_score = max(0.0, min(1.5, level_points + trend_points + 0.5))\n    else:\n        roic_score = 0.75\n\n    # --- Relatieve sterkte (0-2,5 punten): begrensd tussen -20% en +20% ---\n    if result["relatieve_sterkte"] is not None:\n        clamped = min(max(result["relatieve_sterkte"], -20), 20)\n        rs_score = (clamped + 20) / 40 * 2.5\n    else:\n        rs_score = 1.25\n\n    # --- Volume-bevestiging (0-1 punt) ---\n    if result.get("volume_bevestigd") is not None:\n        volume_score = 1.0 if result["volume_bevestigd"] else 0.0\n    else:\n        volume_score = 0.5\n\n    # --- Winst-verrassing (0-1,5 punten): alleen als recent genoeg, anders neutraal ---\n    is_recent_enough = (\n        result.get("weken_sinds_earnings") is not None\n        and result["weken_sinds_earnings"] <= EARNINGS_RELEVANCE_WEEKS\n    )\n    if result.get("earnings_surprise_pct") is not None and is_recent_enough:\n        clamped_surprise = min(max(result["earnings_surprise_pct"], -10), 10)\n        earnings_score = (clamped_surprise + 10) / 20 * 1.5\n    else:\n        earnings_score = 0.75\n\n    # --- Afwijking t.o.v. analisten-koersdoel (0-2 punten) ---\n    # Negatieve afwijking = koers ONDER het koersdoel (\'goedkoop\') -> meer punten\n    if result.get("afwijking_fair_value_pct") is not None:\n        clamped_fv = min(max(result["afwijking_fair_value_pct"], -30), 30)\n        fair_value_score = (30 - clamped_fv) / 60 * 2.0\n    else:\n        fair_value_score = 1.0\n\n    return round(\n        freshness_score + roic_score + rs_score + volume_score + earnings_score + fair_value_score, 2\n    )\n\n\ndef _find_ticker_column(tables):\n    for table in tables:\n        cols_lower = [str(c).lower() for c in table.columns]\n        for candidate in ["ticker", "symbol", "ticker symbol"]:\n            if candidate in cols_lower:\n                col_name = table.columns[cols_lower.index(candidate)]\n                tickers = table[col_name].astype(str).str.strip().tolist()\n                if len(tickers) >= 10:\n                    return tickers\n    return None\n\n\ndef fetch_aex_tickers():\n    try:\n        tables = _fetch_wikipedia_tables("https://en.wikipedia.org/wiki/AEX_index")\n        tickers = _find_ticker_column(tables)\n        if tickers:\n            return [t if t.endswith(".AS") else f"{t}.AS" for t in tickers]\n    except Exception as exc:\n        print(f"Kon AEX-samenstelling niet automatisch ophalen: {exc}")\n    return None\n\n\ndef fetch_nasdaq100_tickers():\n    try:\n        tables = _fetch_wikipedia_tables("https://en.wikipedia.org/wiki/Nasdaq-100")\n        tickers = _find_ticker_column(tables)\n        if tickers:\n            return [t.replace(".", "-") for t in tickers]\n    except Exception as exc:\n        print(f"Kon Nasdaq-100-samenstelling niet automatisch ophalen: {exc}")\n    return None\n\n\ndef fetch_sp500_tickers():\n    try:\n        tables = _fetch_wikipedia_tables("https://en.wikipedia.org/wiki/List_of_S%26P_500_companies")\n        tickers = _find_ticker_column(tables)\n        if tickers:\n            return [t.replace(".", "-") for t in tickers]  # bv. BRK.B -> BRK-B (Yahoo-notatie)\n    except Exception as exc:\n        print(f"Kon S&P 500-samenstelling niet automatisch ophalen: {exc}")\n    return None\n\n\ndef fetch_dax_tickers():\n    try:\n        tables = _fetch_wikipedia_tables("https://en.wikipedia.org/wiki/DAX")\n        tickers = _find_ticker_column(tables)\n        if tickers:\n            return [t if t.endswith(".DE") else f"{t}.DE" for t in tickers]\n    except Exception as exc:\n        print(f"Kon DAX-samenstelling niet automatisch ophalen: {exc}")\n    return None\n\n\ndef fetch_cac40_tickers():\n    try:\n        tables = _fetch_wikipedia_tables("https://en.wikipedia.org/wiki/CAC_40")\n        tickers = _find_ticker_column(tables)\n        if tickers:\n            return [t if t.endswith(".PA") else f"{t}.PA" for t in tickers]\n    except Exception as exc:\n        print(f"Kon CAC40-samenstelling niet automatisch ophalen: {exc}")\n    return None\n\n\ndef build_ticker_list():\n    tickers = []\n\n    aex = fetch_aex_tickers()\n    if aex:\n        print(f"AEX: {len(aex)} tickers opgehaald.")\n        tickers += aex\n    else:\n        print("AEX: automatisch ophalen mislukt, fallback-lijst gebruikt voor dit deel.")\n\n    nasdaq100 = fetch_nasdaq100_tickers()\n    if nasdaq100:\n        print(f"Nasdaq-100 (QQQ): {len(nasdaq100)} tickers opgehaald.")\n        tickers += nasdaq100\n    else:\n        print("Nasdaq-100: automatisch ophalen mislukt, fallback-lijst gebruikt voor dit deel.")\n\n    sp500 = fetch_sp500_tickers()\n    if sp500:\n        print(f"S&P 500: {len(sp500)} tickers opgehaald.")\n        tickers += sp500\n    else:\n        print("S&P 500: automatisch ophalen mislukt, fallback-lijst gebruikt voor dit deel.")\n\n    dax = fetch_dax_tickers()\n    if dax:\n        print(f"DAX: {len(dax)} tickers opgehaald.")\n        tickers += dax\n    else:\n        print("DAX: automatisch ophalen mislukt, fallback-lijst gebruikt voor dit deel.")\n\n    cac40 = fetch_cac40_tickers()\n    if cac40:\n        print(f"CAC 40: {len(cac40)} tickers opgehaald.")\n        tickers += cac40\n    else:\n        print("CAC 40: automatisch ophalen mislukt, fallback-lijst gebruikt voor dit deel.")\n\n    if not tickers:\n        print("Alle ophaal-pogingen mislukt -- volledige fallback-lijst gebruikt.")\n        tickers = FALLBACK_TICKERS\n\n    return sorted(set(tickers))\n\n\ndef fetch_weekly(ticker: str, years: int = YEARS_OF_HISTORY) -> pd.DataFrame:\n    # Ticker().history() i.p.v. yf.download() -- zie fetch_daily() in\n    # screener_daily.py voor de volledige toelichting (bevestigde\n    # yfinance-staleness-bug bij yf.download()).\n    df = yf.Ticker(ticker).history(period=f"{years}y", interval="1d", auto_adjust=True)\n    if df.empty:\n        return df\n    if isinstance(df.columns, pd.MultiIndex):\n        df.columns = [c[0].lower() for c in df.columns]\n    else:\n        df.columns = [c.lower() for c in df.columns]\n    df = df[["open", "high", "low", "close", "volume"]]\n    return resample_to_weekly(df)\n\n\ndef get_roic_data(ticker: str) -> dict:\n    """\n    Schat ROIC (Return On Invested Capital) en de trend t.o.v. vorig jaar,\n    op basis van yfinance\'s jaarlijkse financiele overzichten.\n\n    ROIC = NOPAT / Invested Capital\n      NOPAT       = Operating Income * (1 - belastingtarief)  [we gebruiken 25% als redelijke aanname]\n      Invested Capital = Total Debt + Eigen Vermogen - Cash\n\n    LET OP: dit is een SCHATTING, geen exacte boekhoudkundige ROIC (o.a. door\n    de vaste belastingtarief-aanname), en yfinance\'s fundamentele data is niet\n    voor elk aandeel compleet. Gebruik dit als extra context, niet als\n    doorslaggevend cijfer.\n    """\n    try:\n        ticker_obj = yf.Ticker(ticker)\n        financials = ticker_obj.financials\n        balance_sheet = ticker_obj.balance_sheet\n\n        if financials is None or financials.empty or balance_sheet is None or balance_sheet.empty:\n            return {"roic": None, "roic_vorig_jaar": None, "roic_trend": "onbekend"}\n\n        def get_value(df, possible_row_names, period_col, default=0.0):\n            for name in possible_row_names:\n                if name in df.index:\n                    val = df.loc[name, period_col]\n                    if pd.notna(val):\n                        return float(val)\n            return default\n\n        def compute_roic_for_period(period_col):\n            operating_income = get_value(financials, ["Operating Income", "OperatingIncome"], period_col, default=None)\n            if operating_income is None:\n                return None\n\n            tax_rate = 0.25\n            nopat = operating_income * (1 - tax_rate)\n\n            total_debt = get_value(balance_sheet, ["Total Debt", "TotalDebt"], period_col, default=0.0)\n            total_equity = get_value(\n                balance_sheet, ["Stockholders Equity", "Total Equity Gross Minority Interest",\n                                "StockholdersEquity"], period_col, default=None\n            )\n            if total_equity is None:\n                return None\n            cash = get_value(\n                balance_sheet, ["Cash And Cash Equivalents", "CashAndCashEquivalents"], period_col, default=0.0\n            )\n\n            invested_capital = total_debt + total_equity - cash\n            if invested_capital <= 0:\n                return None\n            return nopat / invested_capital\n\n        periods = list(financials.columns)  # meest recente periode eerst\n        roic_now = compute_roic_for_period(periods[0]) if len(periods) > 0 else None\n        roic_prev = compute_roic_for_period(periods[1]) if len(periods) > 1 else None\n\n        trend = "onbekend"\n        if roic_now is not None and roic_prev is not None:\n            trend = "stijgend" if roic_now > roic_prev else "dalend"\n\n        return {"roic": roic_now, "roic_vorig_jaar": roic_prev, "roic_trend": trend}\n    except Exception as exc:\n        print(f"    (ROIC voor {ticker} kon niet berekend worden: {exc})")\n        return {"roic": None, "roic_vorig_jaar": None, "roic_trend": "onbekend"}\n\n\ndef get_recent_news(ticker: str, max_items: int = 3, days_back: int = 7) -> list:\n    """\n    Haalt de meest recente nieuwsberichten op voor een ticker via Yahoo\n    Finance (yfinance), gefilterd op de laatste \'days_back\' dagen.\n\n    LET OP: yfinance\'s nieuws-dataformaat is in het verleden veranderd\n    tussen versies -- deze functie probeert zowel de oudere als nieuwere\n    veldnamen, en geeft gewoon een lege lijst terug als niets herkend wordt\n    (i.p.v. te crashen).\n    """\n    try:\n        ticker_obj = yf.Ticker(ticker)\n        news_items = ticker_obj.news or []\n    except Exception as exc:\n        print(f"    (Nieuws voor {ticker} kon niet opgehaald worden: {exc})")\n        return []\n\n    cutoff = pd.Timestamp.now(tz="UTC") - pd.Timedelta(days=days_back)\n    results = []\n\n    for item in news_items:\n        # Nieuwere yfinance-versies nesten de velden onder \'content\'; oudere niet.\n        content = item.get("content", item) if isinstance(item, dict) else {}\n\n        title = content.get("title") or item.get("title")\n        provider = content.get("provider") if isinstance(content.get("provider"), dict) else {}\n        publisher = provider.get("displayName") or item.get("publisher")\n        canonical = content.get("canonicalUrl") if isinstance(content.get("canonicalUrl"), dict) else {}\n        link = canonical.get("url") or item.get("link")\n        pub_time = content.get("pubDate") or item.get("providerPublishTime")\n\n        if pub_time is None or title is None:\n            continue\n\n        try:\n            pub_dt = (pd.Timestamp(pub_time, unit="s", tz="UTC")\n                      if isinstance(pub_time, (int, float)) else pd.Timestamp(pub_time, tz="UTC"))\n        except Exception:\n            continue\n\n        if pub_dt < cutoff:\n            continue\n\n        results.append({"title": title, "publisher": publisher or "onbekend", "link": link, "published": pub_dt})\n\n    results.sort(key=lambda x: x["published"], reverse=True)\n    return results[:max_items]\n\n\ndef get_earnings_surprise(ticker: str) -> dict:\n    """\n    Haalt de meest recente winst-verrassing op: rapporteerde het bedrijf\n    beter of slechter dan verwacht bij de laatste kwartaalcijfers?\n\n    Achterliggend idee: \'Post-Earnings-Announcement Drift\' is een van de\n    best gedocumenteerde patronen in de financiele literatuur -- aandelen\n    die beter dan verwacht rapporteren, presteren daarna vaak nog weken\n    tot maanden relatief beter.\n\n    LET OP: yfinance\'s earnings-data is niet voor elk aandeel compleet,\n    vooral niet-Amerikaanse aandelen missen dit vaker.\n    """\n    try:\n        ticker_obj = yf.Ticker(ticker)\n        try:\n            df = ticker_obj.get_earnings_dates(limit=8)\n        except Exception:\n            df = getattr(ticker_obj, "earnings_dates", None)\n\n        if df is None or df.empty:\n            return {"surprise_pct": None, "beat": None, "earnings_date": None}\n\n        reported_col = next((c for c in df.columns if "Reported" in str(c)), None)\n        surprise_col = next((c for c in df.columns if "Surprise" in str(c)), None)\n        if reported_col is None:\n            return {"surprise_pct": None, "beat": None, "earnings_date": None}\n\n        df = df.dropna(subset=[reported_col])\n        if df.empty:\n            return {"surprise_pct": None, "beat": None, "earnings_date": None}\n\n        df = df.sort_index(ascending=False)  # meest recente gerapporteerde cijfers eerst\n        latest = df.iloc[0]\n\n        surprise_pct = float(latest[surprise_col]) if surprise_col and pd.notna(latest[surprise_col]) else None\n        beat = (surprise_pct is not None and surprise_pct > 0)\n\n        return {"surprise_pct": surprise_pct, "beat": beat, "earnings_date": df.index[0]}\n    except Exception as exc:\n        print(f"    (Earnings-data voor {ticker} kon niet opgehaald worden: {exc})")\n        return {"surprise_pct": None, "beat": None, "earnings_date": None}\n\n\ndef get_prior_trend_duration(df: pd.DataFrame, flip_index) -> int:\n    """\n    Hoeveel weken duurde de trend ONMIDDELLIJK VOORAFGAAND aan deze omslag?\n    (dus: hoe lang was de bearish periode vlak v\xc3\xb3\xc3\xb3r deze bullish-flip)\n\n    Dit onderscheidt een \'verse\' omslag na een langere daling/zijwaartse\n    periode van zigzag-ruis binnen een al lopende trend (waarbij een korte\n    terugval steeds snel gevolgd wordt door weer een bullish-omslag).\n    """\n    position = df.index.get_loc(flip_index)\n    if position == 0:\n        return 0\n\n    prior_trend = df["trend_dir"].iloc[position - 1]\n    count = 0\n    i = position - 1\n    while i >= 0 and df["trend_dir"].iloc[i] == prior_trend:\n        count += 1\n        i -= 1\n    return count\n\n\ndef get_fair_value_estimate(ticker: str) -> dict:\n    """\n    Gebruikt de gemiddelde analisten-koersdoel (via yfinance) als schatting\n    van \'fair value\'. Dit is GEEN eigen berekende waardering (geen DCF/\n    P/E-model), maar de consensus-verwachting van professionele analisten\n    -- transparanter dan een zelfverzonnen formule met eigen aannames.\n\n    LET OP: analisten-koersdoelen zijn zelf ook maar schattingen (met eigen\n    aannames, en soms verouderd), en niet voor elk aandeel beschikbaar --\n    vooral kleinere en niet-Amerikaanse aandelen missen dit vaker.\n    """\n    try:\n        ticker_obj = yf.Ticker(ticker)\n        info = ticker_obj.info\n        target = info.get("targetMeanPrice")\n        current = info.get("currentPrice") or info.get("regularMarketPrice")\n\n        if target is None or current is None:\n            return {"fair_value": None, "afwijking_pct": None}\n\n        afwijking_pct = (current / target - 1) * 100\n        return {"fair_value": round(float(target), 2), "afwijking_pct": round(afwijking_pct, 1)}\n    except Exception as exc:\n        print(f"    (Fair value voor {ticker} kon niet opgehaald worden: {exc})")\n        return {"fair_value": None, "afwijking_pct": None}\n\n\ndef compute_volatility(df: pd.DataFrame, lookback: int = 26) -> float:\n    """Jaarlijkse volatiliteit (op basis van wekelijkse rendementen, laatste \'lookback\' weken)."""\n    if len(df) < lookback + 1:\n        return None\n    returns = df["close"].pct_change().dropna().tail(lookback)\n    if len(returns) < 10:\n        return None\n    weekly_std = returns.std()\n    return round(float(weekly_std) * (52 ** 0.5) * 100, 1)\n\n\ndef check_ticker_snowball(ticker: str, df: pd.DataFrame) -> dict:\n    """\n    Snowball Signal: kwalitatief goede aandelen voor een goede prijs, voor\n    de lange-termijn-belegger. GEEN verse trend-omslag nodig -- dit gaat\n    over \'goedkoop + kwalitatief nu\', niet over timing.\n\n    Volgorde bewust: goedkope check (volatiliteit, uit al-opgehaalde\n    koersdata) EERST, dure fundamentele aanroepen (ROIC, fair value) alleen\n    voor kandidaten die de goedkope check al doorstaan.\n    """\n    volatility = compute_volatility(df)\n    if volatility is None or volatility > 30:\n        return None\n\n    roic_data = get_roic_data(ticker)\n    if roic_data["roic"] is None or roic_data["roic"] * 100 < 15 or roic_data["roic_trend"] == "dalend":\n        return None\n\n    fair_value_data = get_fair_value_estimate(ticker)\n    if fair_value_data["afwijking_pct"] is None or fair_value_data["afwijking_pct"] > -10:\n        return None\n\n    return {\n        "ticker": ticker,\n        "prijs_nu": round(float(df["close"].iloc[-1]), 2),\n        "roic_pct": round(roic_data["roic"] * 100, 1),\n        "roic_trend": roic_data["roic_trend"],\n        "fair_value": fair_value_data["fair_value"],\n        "afwijking_fair_value_pct": fair_value_data["afwijking_pct"],\n        "volatiliteit_pct": volatility,\n    }\n\n\ndef check_ticker_rocket(ticker: str, df: pd.DataFrame, benchmark_returns: dict) -> dict:\n    """\n    Rocket List: versnellende groei + momentum, voor de jongere/hippere\n    belegger. GEEN ROIC-eis (groei-aandelen zijn vaak nog niet winstgevend).\n    """\n    if len(df) < 14:\n        return None\n\n    try:\n        info = yf.Ticker(ticker).info\n    except Exception:\n        return None\n    growth_candidates = [\n        g for g in [info.get("revenueGrowth"), info.get("earningsGrowth")] if g is not None\n    ]\n    growth = max(growth_candidates) if growth_candidates else None\n    if growth is None or growth < 0.20:\n        return None\n\n    benchmark_ticker = get_benchmark_for_ticker(ticker)\n    own_return = get_trailing_return_pct(df, BENCHMARK_LOOKBACK_WEEKS)\n    benchmark_return = benchmark_returns.get(benchmark_ticker)\n    if own_return is None or benchmark_return is None:\n        return None\n    relative_strength = own_return - benchmark_return\n    if relative_strength <= 0:\n        return None  # moet sterker zijn dan de markt\n\n    # Versnelling: is het rendement van de laatste maand hoger dan het\n    # GEMIDDELDE maand-tempo van de laatste 3 maanden? (puur prijsactie,\n    # geen nieuwe databron nodig)\n    own_return_1m = get_trailing_return_pct(df, 4)\n    own_return_3m = get_trailing_return_pct(df, 13)\n    if own_return_1m is None or own_return_3m is None:\n        return None\n    monthly_pace_3m = own_return_3m / 3\n    if own_return_1m <= monthly_pace_3m:\n        return None\n\n    return {\n        "ticker": ticker,\n        "prijs_nu": round(float(df["close"].iloc[-1]), 2),\n        "groei_pct": round(growth * 100, 1),\n        "relatieve_sterkte": round(relative_strength, 2),\n        "rendement_1m_pct": round(own_return_1m, 2),\n        "rendement_3m_pct": round(own_return_3m, 2),\n    }\n\n\ndef check_ticker(ticker: str, benchmark_returns: dict, df: pd.DataFrame = None):\n    if df is None:\n        try:\n            df = fetch_weekly(ticker)\n        except Exception as exc:\n            print(f"  {ticker}: fout bij ophalen ({exc})")\n            return None\n\n    min_needed = max(ATR_LENGTH, TREND_FILTER_EMA_LENGTH) + 5\n    if df.empty or len(df) < min_needed:\n        print(f"  {ticker}: te weinig data (nodig: {min_needed}, gekregen: {len(df)})")\n        return None\n\n    st = supertrend(df, length=ATR_LENGTH, multiplier=ATR_MULTIPLIER)\n    df = df.copy()\n    df["trend_dir"] = st["trend_dir"]\n    df["ema_trend"] = ema(df["close"], TREND_FILTER_EMA_LENGTH)\n    df["volume_ratio"] = volume_ratio(df["volume"], length=VOLUME_AVG_WEEKS)\n\n    flips = df.index[(df["trend_dir"] == 1) & (df["trend_dir"].shift(1) == -1)]\n    if len(flips) == 0:\n        return None\n\n    last_flip = flips[-1]\n    weeks_since_flip = len(df.loc[last_flip:]) - 1\n    if weeks_since_flip > LOOKBACK_WEEKS_FOR_SIGNAL:\n        return None\n\n    prior_trend_weeks = get_prior_trend_duration(df, last_flip)\n    if prior_trend_weeks < MIN_PRIOR_TREND_WEEKS:\n        return None  # waarschijnlijk zigzag-ruis binnen een al lopende trend, geen \'verse\' omslag\n\n    flip_row = df.loc[last_flip]\n    latest_row = df.iloc[-1]\n\n    # Relatieve sterkte: hoe deed dit aandeel het t.o.v. de relevante index,\n    # over dezelfde trailing periode? Positief = sterker dan de markt.\n    benchmark_ticker = get_benchmark_for_ticker(ticker)\n    own_return = get_trailing_return_pct(df, BENCHMARK_LOOKBACK_WEEKS)\n    benchmark_return = benchmark_returns.get(benchmark_ticker)\n    relative_strength = (\n        round(own_return - benchmark_return, 2)\n        if own_return is not None and benchmark_return is not None\n        else None\n    )\n\n    # Volume-bevestiging: was het volume op de omslag-week hoger dan gemiddeld?\n    volume_confirmed = (\n        bool(flip_row["volume_ratio"] > 1) if pd.notna(flip_row["volume_ratio"]) else None\n    )\n\n    result = {\n        "ticker": ticker,\n        "flip_date": last_flip.date(),\n        "weken_geleden": weeks_since_flip,\n        "voorgaande_trend_weken": prior_trend_weeks,\n        "prijs_bij_omslag": round(float(flip_row["close"]), 2),\n        "prijs_nu": round(float(latest_row["close"]), 2),\n        "sinds_omslag_pct": round((latest_row["close"] / flip_row["close"] - 1) * 100, 2),\n        "boven_ema20": bool(latest_row["close"] > latest_row["ema_trend"]),\n        "benchmark": benchmark_ticker,\n        "relatieve_sterkte": relative_strength,\n        "volume_bevestigd": volume_confirmed,\n    }\n\n    # ROIC en winst-verrassing alleen berekenen voor tickers die al een\n    # technisch signaal hebben (bespaart onnodige extra aanroepen)\n    roic_data = get_roic_data(ticker)\n    result["roic_pct"] = round(roic_data["roic"] * 100, 1) if roic_data["roic"] is not None else None\n    result["roic_trend"] = roic_data["roic_trend"]\n\n    earnings_data = get_earnings_surprise(ticker)\n    result["earnings_surprise_pct"] = (\n        round(earnings_data["surprise_pct"], 1) if earnings_data["surprise_pct"] is not None else None\n    )\n    result["earnings_beat"] = earnings_data["beat"]\n    result["earnings_date"] = (\n        earnings_data["earnings_date"].date() if earnings_data["earnings_date"] is not None else None\n    )\n    if earnings_data["earnings_date"] is not None:\n        days_since = (pd.Timestamp.now(tz=earnings_data["earnings_date"].tz) - earnings_data["earnings_date"]).days\n        result["weken_sinds_earnings"] = max(0, days_since // 7)\n    else:\n        result["weken_sinds_earnings"] = None\n\n    fair_value_data = get_fair_value_estimate(ticker)\n    result["fair_value"] = fair_value_data["fair_value"]\n    result["afwijking_fair_value_pct"] = fair_value_data["afwijking_pct"]\n\n    result["score"] = compute_score(result)\n\n    return result\n\n\ndef build_email_body(df_hits: pd.DataFrame) -> tuple:\n    lines = [f"Supertrend-screener: {len(df_hits)} signalen gevonden (gesorteerd op score, hoogste eerst).\\n"]\n    for _, row in df_hits.iterrows():\n        roic_txt = f"{row[\'roic_pct\']:+.1f}% ({row[\'roic_trend\']})" if row[\'roic_pct\'] is not None else "onbekend"\n        rs_txt = f"{row[\'relatieve_sterkte\']:+.2f}% vs {row[\'benchmark\']}" if row[\'relatieve_sterkte\'] is not None else "onbekend"\n        vol_txt = ("ja" if row[\'volume_bevestigd\'] is True else "nee" if row[\'volume_bevestigd\'] is False else "onbekend")\n        earn_txt = (\n            f"{row[\'earnings_surprise_pct\']:+.1f}% op {row[\'earnings_date\']} ({row[\'weken_sinds_earnings\']}w geleden)"\n            if row[\'earnings_surprise_pct\'] is not None else "onbekend"\n        )\n        fv_txt = (\n            f"{row[\'fair_value\']} (koers {row[\'afwijking_fair_value_pct\']:+.1f}% t.o.v. dit koersdoel)"\n            if row[\'fair_value\'] is not None else "onbekend"\n        )\n        lines.append(\n            f"- [score {row[\'score\']}] {row[\'ticker\']}: omslag op {row[\'flip_date\']} "\n            f"({row[\'weken_geleden\']} week(en) geleden, na {row[\'voorgaande_trend_weken\']} weken bearish), "\n            f"prijs toen {row[\'prijs_bij_omslag\']}, "\n            f"nu {row[\'prijs_nu\']} ({row[\'sinds_omslag_pct\']:+.2f}%), "\n            f"boven EMA20: {\'ja\' if row[\'boven_ema20\'] else \'nee\'}, "\n            f"ROIC: {roic_txt}, relatieve sterkte: {rs_txt}, "\n            f"volume-bevestiging: {vol_txt}, winst-verrassing: {earn_txt}, "\n            f"analisten-koersdoel: {fv_txt}"\n        )\n    text_body = "\\n".join(lines)\n    text_body += "\\n\\nDit is een screener, geen koopadvies. Doe altijd je eigen verdere afweging."\n\n    def _format_row_html(r):\n        roic_str = f"{r[\'roic_pct\']:+.1f}%" if r[\'roic_pct\'] is not None else "-"\n        rs_str = f"{r[\'relatieve_sterkte\']:+.2f}%" if r[\'relatieve_sterkte\'] is not None else "-"\n        vol_str = "ja" if r[\'volume_bevestigd\'] is True else ("nee" if r[\'volume_bevestigd\'] is False else "-")\n        earn_str = (\n            f"{r[\'earnings_surprise_pct\']:+.1f}% ({r[\'weken_sinds_earnings\']}w geleden)"\n            if r[\'earnings_surprise_pct\'] is not None else "-"\n        )\n        fv_str = (\n            f"{r[\'fair_value\']} ({r[\'afwijking_fair_value_pct\']:+.1f}%)"\n            if r[\'fair_value\'] is not None else "-"\n        )\n        return (\n            f"<tr><td><b>{r[\'score\']}</b></td><td>{r[\'ticker\']}</td><td>{r[\'flip_date\']}</td><td>{r[\'weken_geleden\']}</td>"\n            f"<td>{r[\'voorgaande_trend_weken\']}</td>"\n            f"<td>{r[\'prijs_bij_omslag\']}</td><td>{r[\'prijs_nu\']}</td>"\n            f"<td>{r[\'sinds_omslag_pct\']:+.2f}%</td><td>{\'ja\' if r[\'boven_ema20\'] else \'nee\'}</td>"\n            f"<td>{roic_str}</td><td>{r[\'roic_trend\']}</td><td>{rs_str}</td>"\n            f"<td>{vol_str}</td><td>{earn_str}</td><td>{fv_str}</td></tr>"\n        )\n\n    rows_html = "".join(_format_row_html(r) for _, r in df_hits.iterrows())\n    html_body = f"""\n    <h3>Supertrend-screener: {len(df_hits)} signalen gevonden</h3>\n    <p>Gesorteerd op score (hoogste eerst) -- combinatie van versheid, ROIC-niveau/-trend,\n    relatieve sterkte, volume-bevestiging, en winst-verrassing.</p>\n    <table border="1" cellpadding="5" cellspacing="0">\n      <tr><th>Score</th><th>Ticker</th><th>Omslag-datum</th><th>Weken geleden</th>\n          <th>Voorgaande trend (weken)</th>\n          <th>Prijs bij omslag</th><th>Prijs nu</th><th>Sinds omslag</th><th>Boven EMA20</th>\n          <th>ROIC</th><th>ROIC-trend</th><th>Rel. sterkte</th>\n          <th>Volume-bevestiging</th><th>Winst-verrassing</th><th>Analisten-koersdoel (afwijking)</th></tr>\n      {rows_html}\n    </table>\n    <p><i>Dit is een screener, geen koopadvies. Doe altijd je eigen verdere afweging.</i></p>\n    <p><i>ROIC en winst-verrassing zijn schattingen op basis van yfinance-data, niet elke\n    ticker heeft complete gegevens. De score is een simpele, ongeoptimaliseerde optelsom --\n    geen gevalideerde voorspeller.</i></p>\n    """\n    return text_body, html_body\n\n\ndef main(send_own_email: bool = True) -> None:\n    tickers = TICKERS if TICKERS is not None else build_ticker_list()\n\n    print("Benchmark-rendementen ophalen (voor relatieve sterkte)...")\n    benchmark_returns = fetch_benchmark_returns()\n    for bench, ret in benchmark_returns.items():\n        print(f"  {bench}: {f\'{ret:+.2f}%\' if ret is not None else \'onbekend\'} "\n              f"(laatste {BENCHMARK_LOOKBACK_WEEKS} weken)")\n\n    print(f"\\nScreening {len(tickers)} tickers op recente bullish Supertrend-omslag "\n          f"(weekly, ATR-periode {ATR_LENGTH}, multiplier {ATR_MULTIPLIER})...")\n    print("(Dit kan enkele minuten duren bij een grote lijst zoals AEX + Nasdaq-100.)\\n")\n\n    hits = []\n    snowball_hits = []\n    rocket_hits = []\n    for ticker in tickers:\n        try:\n            df = fetch_weekly(ticker)\n        except Exception as exc:\n            print(f"  {ticker}: fout bij ophalen ({exc})")\n            continue\n\n        result = check_ticker(ticker, benchmark_returns, df=df)\n        if result:\n            hits.append(result)\n            print(f"  {ticker}: MOMENTOCRATS-SIGNAAL ({result[\'weken_geleden\']} week(en) geleden, score {result[\'score\']})")\n        else:\n            print(f"  {ticker}: geen Momentocrats-signaal")\n\n        # Snowball en Rocket List zijn ONAFHANKELIJK van een verse omslag --\n        # hergebruiken dezelfde, al opgehaalde koersdata (geen extra API-aanroepen)\n        snowball_result = check_ticker_snowball(ticker, df)\n        if snowball_result:\n            snowball_hits.append(snowball_result)\n            print(f"    -> Snowball Signal: {ticker}")\n\n        rocket_result = check_ticker_rocket(ticker, df, benchmark_returns)\n        if rocket_result:\n            rocket_hits.append(rocket_result)\n            print(f"    -> Rocket List: {ticker}")\n\n    if snowball_hits:\n        pd.DataFrame(snowball_hits).sort_values("afwijking_fair_value_pct").to_csv(\n            "snowball_signals.csv", index=False\n        )\n        print(f"\\n{len(snowball_hits)} Snowball Signal(s) opgeslagen naar \'snowball_signals.csv\'.")\n\n    if rocket_hits:\n        pd.DataFrame(rocket_hits).sort_values("groei_pct", ascending=False).to_csv(\n            "rocket_list_signals.csv", index=False\n        )\n        print(f"{len(rocket_hits)} Rocket List-signaal/signalen opgeslagen naar \'rocket_list_signals.csv\'.")\n\n    if not hits:\n        print(f"\\nGeen enkel aandeel had de afgelopen {LOOKBACK_WEEKS_FOR_SIGNAL} "\n              f"week(en) een bullish omslag.")\n        if send_own_email and email_is_configured():\n            send_email(\n                subject="Supertrend-screener: geen signalen deze week",\n                body_text=f"Geen van de {len(tickers)} gescreende tickers had de afgelopen "\n                          f"{LOOKBACK_WEEKS_FOR_SIGNAL} week(en) een bullish Supertrend-omslag.",\n            )\n        return\n\n    df_hits = pd.DataFrame(hits)\n    df_hits.sort_values("score", ascending=False, inplace=True)\n\n    print(f"\\n=== {len(hits)} SIGNALEN GEVONDEN ===\\n")\n    # Voor de terminal-weergave: NaN in roic_pct netjes als \'onbekend\' tonen\n    # (de CSV-export blijft wel de kale numerieke waarde/NaN bevatten, handig\n    # als je de data later zelf verder wil verwerken)\n    display_df = df_hits.copy()\n    display_df["roic_pct"] = display_df["roic_pct"].apply(lambda v: "onbekend" if pd.isna(v) else v)\n    display_df["relatieve_sterkte"] = display_df["relatieve_sterkte"].apply(lambda v: "onbekend" if pd.isna(v) else v)\n    display_df["volume_bevestigd"] = display_df["volume_bevestigd"].apply(lambda v: "onbekend" if pd.isna(v) else v)\n    display_df["earnings_surprise_pct"] = display_df["earnings_surprise_pct"].apply(lambda v: "onbekend" if pd.isna(v) else v)\n    display_df["weken_sinds_earnings"] = display_df["weken_sinds_earnings"].apply(lambda v: "onbekend" if pd.isna(v) else v)\n    display_df["fair_value"] = display_df["fair_value"].apply(lambda v: "onbekend" if pd.isna(v) else v)\n    display_df["afwijking_fair_value_pct"] = display_df["afwijking_fair_value_pct"].apply(lambda v: "onbekend" if pd.isna(v) else v)\n    print(display_df.to_string(index=False))\n\n    df_hits.to_csv("supertrend_signals.csv", index=False)\n    print("\\nOpgeslagen in \'supertrend_signals.csv\'.")\n    print("\\nLET OP: dit is een screener, geen koopadvies. Doe altijd je eigen")\n    print("verdere afweging (fundamentals, nieuws, sector, waardering) voordat")\n    print("je op basis hiervan een positie overweegt.")\n\n    if send_own_email and email_is_configured():\n        text_body, html_body = build_email_body(df_hits)\n        send_email(\n            subject=f"Supertrend-screener: {len(hits)} nieuwe signalen",\n            body_text=text_body,\n            body_html=html_body,\n        )\n    else:\n        print("\\n(E-mail niet verstuurd: EMAIL_ADDRESS/EMAIL_APP_PASSWORD/EMAIL_TO "\n              "nog niet ingesteld in .env.)")\n\n\nif __name__ == "__main__":\n    main()\n'
SCREENER_DAILY_CONTENT = b'"""\nDagelijkse variant van screener.py -- zelfde signaal-logica (Supertrend-\nomslag + ROIC + winst-verrassing + fair value + relatieve sterkte), maar\nop DAGELIJKSE candles i.p.v. wekelijkse, met instellingen die daarbij\npassen (kortere periodes). Bedoeld voor swing trades (dagen-weken), naast\nde bestaande wekelijkse screener (voor lange-termijn-overtuigingen).\n\nBewust een APART bestand i.p.v. de bestaande, uitgebreid-afgestelde\nscreener.py aan te passen -- dat voorkomt dat wijzigingen hier de\ngoed-werkende wekelijkse screener zouden kunnen breken. Hergebruikt wel\nalle tijdschaal-onafhankelijke bouwstenen (tickerlijsten, ROIC,\nwinst-verrassing, fair value, nieuws) via import.\n\nGebruik: python screener_daily.py\n"""\nfrom __future__ import annotations\n\nimport pandas as pd\nimport yfinance as yf\n\nfrom macro_events import get_todays_macro_events\n\nfrom indicators import supertrend, ema, volume_ratio\nfrom screener import (\n    FALLBACK_TICKERS, BENCHMARKS, DEFAULT_BENCHMARK,\n    fetch_aex_tickers, fetch_nasdaq100_tickers, fetch_sp500_tickers,\n    fetch_dax_tickers, fetch_cac40_tickers, build_ticker_list,\n    get_benchmark_for_ticker, get_trailing_return_pct, get_prior_trend_duration,\n    get_roic_data, get_earnings_surprise, get_fair_value_estimate,\n)\nfrom emailer import send_email, is_configured as email_is_configured\n\n# --- Instellingen, geschaald voor dagelijkse candles (i.p.v. wekelijkse) ---\nATR_LENGTH = 10\nATR_MULTIPLIER = 3.0\nLOOKBACK_DAYS_FOR_SIGNAL = 2       # hoe \'vers\' een omslag moet zijn (i.p.v. 2 WEKEN bij de wekelijkse variant)\nTREND_FILTER_EMA_LENGTH = 50       # bredere-trend-context (i.p.v. 20 WEKEN)\nYEARS_OF_HISTORY = 2\nBENCHMARK_LOOKBACK_DAYS = 60       # relatieve-sterkte-vergelijkingsperiode (i.p.v. 12 WEKEN)\nVOLUME_AVG_DAYS = 20\nMIN_PRIOR_TREND_DAYS = 15          # zigzag-ruis-filter (i.p.v. 8 WEKEN)\nEARNINGS_RELEVANCE_DAYS = 45       # hoe recent winstcijfers moeten zijn (i.p.v. 8 WEKEN)\n\n\ndef fetch_daily(ticker: str, years: int = YEARS_OF_HISTORY) -> pd.DataFrame:\n    """\n    Haalt dagelijkse OHLCV-data op -- GEEN resampling naar weekly, in\n    tegenstelling tot screener.py.\n\n    Bevat een verstheids-check: yfinance\'s databron loopt soms 1+\n    handelsdag achter op het moment dat deze scan draait (een bekend,\n    terugkerend probleem -- bevestigd via meerdere GitHub-issues over\n    \'laatste dag\'-data die niet klopt). Zonder deze check zou een positie\n    stilzwijgend met verouderde cijfers getoond worden (bv. \'Since: 0d\n    ago\' terwijl het eigenlijk 2 handelsdagen geleden was, met een\n    0,00%-koersverandering die niet klopt omdat de \'omslag\'- en\n    \'huidige\'-koers toevallig dezelfde, verouderde rij zijn).\n\n    Vergelijkt NIET met een vast aantal dagen (dat zou een normale\n    maandagochtend-achterstand tot vrijdag, 3 kalenderdagen, ten onrechte\n    als verdacht bestempelen) -- maar met de VERWACHTE meest recente\n    handelsdag, rekening houdend met het weekend, plus 1 dag speling voor\n    incidentele feestdagen.\n    """\n    # Ticker().history() i.p.v. yf.download() -- die laatste bleek in\n    # yfinance\'s eigen GitHub-issues bevestigd de laatste handelsdag te\n    # kunnen missen (structureel 1+ dag achterlopend), een fix die eerder\n    # al is toegepast op de live portfolio-data in dashboard.py. Hier\n    # minder kritiek (supertrend-signalen kijken naar meerdaagse/wekelijkse\n    # patronen, niet dag-op-dag), maar voor consistentie ook hier toegepast.\n    df = yf.Ticker(ticker).history(period=f"{years}y", interval="1d", auto_adjust=True)\n    if df.empty:\n        return df\n    if isinstance(df.columns, pd.MultiIndex):\n        df.columns = [c[0].lower() for c in df.columns]\n    else:\n        df.columns = [c.lower() for c in df.columns]\n    df = df[["open", "high", "low", "close", "volume"]]\n    # yfinance geeft soms een \'vandaag\'-rij terug voordat de beurs een\n    # geldige slotkoers heeft (bv. vroeg op de ochtend, vlak na het\n    # openen van de scan) -- die rij heeft dan NaN in \'close\'. Zonder\n    # deze filter zou die NaN als \'prijs_nu\' gebruikt worden, en\n    # (aangezien score ook op de laatste koers steunt) ook de score\n    # zelf NaN maken -- precies wat een \'nan\' overal in de mail geeft.\n    df = df[df["close"].notna()]\n\n    if not df.empty:\n        last_date = df.index[-1]\n        if getattr(last_date, "tz", None) is not None:\n            last_date = last_date.tz_localize(None)\n        today = pd.Timestamp.now().normalize()\n        weekday = today.dayofweek  # maandag=0 ... zondag=6\n        # BEWUST geen ruime buffer op doordeweekse dagen (dinsdag-vrijdag) --\n        # een 1-dags-speling zou precies de waargenomen bug (2 handelsdagen\n        # achterstand) ook goedkeuren, en \'m dus onzichtbaar maken. Alleen\n        # rond maandag iets meer ruimte (voor een mogelijke vrijdag-\n        # feestdag) -- die 3-daagse weekend-sprong is al normaal, dus 1\n        # dag extra dekt een incidentele feestdag zonder de vaste\n        # weekend-sprong zelf te flaggen.\n        if weekday == 0:      # maandag\n            max_days_back = 4\n        elif weekday == 6:    # zondag (draait normaal niet, voor de zekerheid)\n            max_days_back = 3\n        else:                  # dinsdag t/m vrijdag\n            max_days_back = 1\n        oldest_acceptable_date = today - pd.Timedelta(days=max_days_back)\n\n        if last_date < oldest_acceptable_date:\n            days_stale = (today - last_date).days\n            print(f"    (Overgeslagen: laatste data voor {ticker} is {days_stale} dag(en) oud "\n                  f"(laatste koers: {last_date.date()}) -- waarschijnlijk yfinance-vertraging, "\n                  f"niet betrouwbaar genoeg voor vandaag.)")\n            return pd.DataFrame()\n\n    return df\n\n\ndef fetch_benchmark_returns_daily() -> dict:\n    """Haalt voor elke benchmark-index 1x het trailing-rendement op (dagelijkse basis)."""\n    returns = {}\n    for benchmark_ticker in set(list(BENCHMARKS.values()) + [DEFAULT_BENCHMARK]):\n        try:\n            df_bench = fetch_daily(benchmark_ticker)\n            returns[benchmark_ticker] = get_trailing_return_pct(df_bench, BENCHMARK_LOOKBACK_DAYS)\n        except Exception as exc:\n            print(f"Kon benchmark {benchmark_ticker} niet ophalen: {exc}")\n            returns[benchmark_ticker] = None\n    return returns\n\n\ndef compute_score_daily(result: dict) -> float:\n    """\n    Zelfde score-opbouw als screener.py\'s compute_score (0-10, dezelfde\n    gewichten), maar met dag-gebaseerde versheid/relevantie-drempels i.p.v.\n    week-gebaseerde.\n    """\n    freshness_score = max(0.0, (LOOKBACK_DAYS_FOR_SIGNAL - result["dagen_geleden"]) / LOOKBACK_DAYS_FOR_SIGNAL * 1.5)\n\n    if result["roic_pct"] is not None:\n        level_points = min(max(result["roic_pct"], 0), 30) / 30 * 1.0\n        trend_points = 0.5 if result["roic_trend"] == "stijgend" else (-0.5 if result["roic_trend"] == "dalend" else 0)\n        roic_score = max(0.0, min(1.5, level_points + trend_points + 0.5))\n    else:\n        roic_score = 0.75\n\n    if result["relatieve_sterkte"] is not None:\n        clamped = min(max(result["relatieve_sterkte"], -20), 20)\n        rs_score = (clamped + 20) / 40 * 2.5\n    else:\n        rs_score = 1.25\n\n    if result.get("volume_bevestigd") is not None:\n        volume_score = 1.0 if result["volume_bevestigd"] else 0.0\n    else:\n        volume_score = 0.5\n\n    is_recent_enough = (\n        result.get("dagen_sinds_earnings") is not None\n        and result["dagen_sinds_earnings"] <= EARNINGS_RELEVANCE_DAYS\n    )\n    if result.get("earnings_surprise_pct") is not None and is_recent_enough:\n        clamped_surprise = min(max(result["earnings_surprise_pct"], -10), 10)\n        earnings_score = (clamped_surprise + 10) / 20 * 1.5\n    else:\n        earnings_score = 0.75\n\n    if result.get("afwijking_fair_value_pct") is not None:\n        clamped_fv = min(max(result["afwijking_fair_value_pct"], -30), 30)\n        fair_value_score = (30 - clamped_fv) / 60 * 2.0\n    else:\n        fair_value_score = 1.0\n\n    return round(\n        freshness_score + roic_score + rs_score + volume_score + earnings_score + fair_value_score, 2\n    )\n\n\ndef check_ticker_daily(ticker: str, benchmark_returns: dict, df: pd.DataFrame = None):\n    if df is None:\n        try:\n            df = fetch_daily(ticker)\n        except Exception as exc:\n            print(f"  {ticker}: fout bij ophalen ({exc})")\n            return None\n\n    min_needed = max(ATR_LENGTH, TREND_FILTER_EMA_LENGTH) + 5\n    if df.empty or len(df) < min_needed:\n        print(f"  {ticker}: te weinig data (nodig: {min_needed}, gekregen: {len(df)})")\n        return None\n\n    st = supertrend(df, length=ATR_LENGTH, multiplier=ATR_MULTIPLIER)\n    df = df.copy()\n    df["trend_dir"] = st["trend_dir"]\n    df["ema_trend"] = ema(df["close"], TREND_FILTER_EMA_LENGTH)\n    df["volume_ratio"] = volume_ratio(df["volume"], length=VOLUME_AVG_DAYS)\n\n    flips = df.index[(df["trend_dir"] == 1) & (df["trend_dir"].shift(1) == -1)]\n    if len(flips) == 0:\n        return None\n\n    last_flip = flips[-1]\n    days_since_flip = len(df.loc[last_flip:]) - 1\n    if days_since_flip > LOOKBACK_DAYS_FOR_SIGNAL:\n        return None\n\n    prior_trend_days = get_prior_trend_duration(df, last_flip)\n    if prior_trend_days < MIN_PRIOR_TREND_DAYS:\n        return None  # waarschijnlijk zigzag-ruis binnen een al lopende trend\n\n    flip_row = df.loc[last_flip]\n    latest_row = df.iloc[-1]\n\n    benchmark_ticker = get_benchmark_for_ticker(ticker)\n    own_return = get_trailing_return_pct(df, BENCHMARK_LOOKBACK_DAYS)\n    benchmark_return = benchmark_returns.get(benchmark_ticker)\n    relative_strength = (\n        round(own_return - benchmark_return, 2)\n        if own_return is not None and benchmark_return is not None\n        else None\n    )\n\n    volume_confirmed = (\n        bool(flip_row["volume_ratio"] > 1) if pd.notna(flip_row["volume_ratio"]) else None\n    )\n\n    result = {\n        "ticker": ticker,\n        "flip_date": last_flip.date(),\n        "dagen_geleden": days_since_flip,\n        "voorgaande_trend_dagen": prior_trend_days,\n        "prijs_bij_omslag": round(float(flip_row["close"]), 2),\n        "prijs_nu": round(float(latest_row["close"]), 2),\n        "sinds_omslag_pct": round((latest_row["close"] / flip_row["close"] - 1) * 100, 2),\n        "boven_ema": bool(latest_row["close"] > latest_row["ema_trend"]),\n        "benchmark": benchmark_ticker,\n        "relatieve_sterkte": relative_strength,\n        "volume_bevestigd": volume_confirmed,\n    }\n\n    roic_data = get_roic_data(ticker)\n    result["roic_pct"] = round(roic_data["roic"] * 100, 1) if roic_data["roic"] is not None else None\n    result["roic_trend"] = roic_data["roic_trend"]\n\n    earnings_data = get_earnings_surprise(ticker)\n    result["earnings_surprise_pct"] = (\n        round(earnings_data["surprise_pct"], 1) if earnings_data["surprise_pct"] is not None else None\n    )\n    result["earnings_beat"] = earnings_data["beat"]\n    result["earnings_date"] = (\n        earnings_data["earnings_date"].date() if earnings_data["earnings_date"] is not None else None\n    )\n    if earnings_data["earnings_date"] is not None:\n        days_since_earnings = (pd.Timestamp.now(tz=earnings_data["earnings_date"].tz) - earnings_data["earnings_date"]).days\n        result["dagen_sinds_earnings"] = max(0, days_since_earnings)\n    else:\n        result["dagen_sinds_earnings"] = None\n\n    fair_value_data = get_fair_value_estimate(ticker)\n    result["fair_value"] = fair_value_data["fair_value"]\n    result["afwijking_fair_value_pct"] = fair_value_data["afwijking_pct"]\n\n    result["score"] = compute_score_daily(result)\n\n    return result\n\n\ndef _get_macro_teaser_text() -> str:\n    """\n    Geeft 1 korte teaser-regel terug als er vandaag een macro-event is\n    (CPI/FOMC/ECB), anders None -- bewust maar 1 regel, alleen op de\n    dagen dat het er toe doet, geen volledige kalender (dat zou de mail\n    te vol maken en de prikkel om naar de site te gaan verminderen).\n    """\n    events = get_todays_macro_events(max_items=1)\n    if not events:\n        return None\n    e = events[0]\n    return f"Also today: {e[\'name\']} ({e[\'time\']})"\n\n\ndef build_no_signals_email_daily(name: str = None) -> tuple:\n    """Korte, warme mail voor een dag zonder signalen -- houdt het dagelijkse contactmoment in stand."""\n    greeting = f"Good morning, {name}" if name else "Good morning"\n    macro_teaser = _get_macro_teaser_text()\n    macro_line_text = f"\\n{macro_teaser}\\n" if macro_teaser else ""\n    macro_line_html = (\n        f\'<p style="margin-top:12px; font-size:13px; color:#1FAE96; font-weight:600;">\xf0\x9f\x93\x85 {macro_teaser}</p>\'\n        if macro_teaser else ""\n    )\n\n    text_body = (\n        f"{greeting} from Hesty\'s\\n\\n"\n        "No bullish flips showed up on today\'s scan -- a quiet day on that front.\\n"\n        f"{macro_line_text}\\n"\n        "Check Discover for sector/theme rotation and earnings surprises, Today for macro events "\n        "and yesterday\'s biggest movers, or Analyse for your own portfolio.\\n\\n"\n        "-- Hesty\'s, your personal investment assistant\\n\\n"\n        "This is a screener, not investment advice."\n    )\n    html_body = f"""\n    <div style="font-family: -apple-system, \'Segoe UI\', Roboto, Arial, sans-serif; max-width: 600px; margin: 0 auto; background:#ffffff;">\n        <div style="background:#101825; padding: 28px 24px; border-radius: 12px 12px 0 0;">\n            <div style="color:#1FAE96; font-size:13px; font-weight:600; letter-spacing:1px; text-transform:uppercase;">Hesty\'s Daily</div>\n            <div style="color:#EAEDF1; font-size:22px; font-weight:700; margin-top:4px;">{greeting}</div>\n        </div>\n        <div style="padding: 24px; border: 1px solid #E5E8EC; border-top: none; border-radius: 0 0 12px 12px;">\n            <p style="font-size:15px; color:#101825; line-height:1.5; margin-top:0;">\n                No bullish flips showed up on today\'s scan -- a quiet day on that front.\n            </p>\n            {macro_line_html}\n            <p style="margin-top:16px; font-size:14px; color:#5B6472; line-height:1.5;">\n                Check <a href="https://hestys.streamlit.app/discover" style="color:#1FAE96; font-weight:600; text-decoration:none;">Discover</a>\n                for sector/theme rotation and earnings surprises,\n                <a href="https://hestys.streamlit.app/today" style="color:#1FAE96; font-weight:600; text-decoration:none;">Today</a>\n                for macro events and yesterday\'s biggest movers, or\n                <a href="https://hestys.streamlit.app/analyze" style="color:#1FAE96; font-weight:600; text-decoration:none;">Analyse</a> for your own portfolio.\n            </p>\n            <p style="margin-top:24px; font-size:14px; color:#101825; font-weight:600;">&mdash; Hesty\'s, your personal investment assistant</p>\n            <p style="margin-top:16px; font-size:12px; color:#9AA1AC; font-style:italic;">This is a screener, not investment advice.</p>\n        </div>\n    </div>\n    """\n    return text_body, html_body\n\n\ndef build_email_body_daily(df_hits: pd.DataFrame, name: str = None) -> tuple:\n    """\n    Bouwt de dagelijkse mail -- zakelijk maar met een eigen stem: een korte,\n    op de data gebaseerde toelichting (geen hype, geen giswerk) vooraf, dan\n    de tabel, en een korte, herkenbare afsluiting namens Hesty\'s.\n\n    \'name\' (optioneel): voor een persoonlijke aanhef (\'Good morning, [naam]\')\n    -- alleen bekend bij ingelogde gebruikers (via user_identity), niet bij\n    de niet-ingelogde e-mail-opt-in-abonnees, die krijgen de neutrale versie.\n    """\n    n = len(df_hits)\n    top_pick = df_hits.iloc[0]  # df_hits is al gesorteerd op score (hoog naar laag)\n    greeting = f"Good morning, {name}" if name else "Good morning"\n\n    intro_line = (\n        f"{n} stock{\'s\' if n != 1 else \'\'} just flipped bullish on today\'s scan. "\n        f"{top_pick[\'ticker\']} leads with the highest score ({top_pick[\'score\']})."\n    )\n    macro_teaser = _get_macro_teaser_text()\n\n    # --- Tekst-versie ---\n    text_lines = [\n        f"{greeting} from Hesty\'s",\n        "",\n        intro_line,\n    ]\n    if macro_teaser:\n        text_lines.append(macro_teaser)\n    text_lines += [\n        "",\n        "Today\'s signals (highest score first):",\n    ]\n    for _, row in df_hits.iterrows():\n        text_lines.append(\n            f"- [{row[\'score\']}] {row[\'ticker\']} (https://finance.yahoo.com/quote/{row[\'ticker\']}): "\n            f"flipped {row[\'dagen_geleden\']} day(s) ago after {row[\'voorgaande_trend_dagen\']} days bearish -- "\n            f"{row[\'prijs_bij_omslag\']} -> {row[\'prijs_nu\']} ({row[\'sinds_omslag_pct\']:+.2f}%)"\n        )\n    text_lines += [\n        "",\n        "See sector/theme rotation and earnings surprises under Discover on the site, "\n        "or check Today for macro events and yesterday\'s biggest movers.",\n        "",\n        "-- Hesty\'s, your personal investment assistant",\n        "",\n        "This is a screener, not investment advice.",\n    ]\n    text_body = "\\n".join(text_lines)\n\n    # --- HTML-versie: lichte achtergrond (betrouwbaarder in e-mail-clients\n    # dan een donkere), met de merk-kleur (jade) als accent ---\n    rows_html = "".join(\n        f"""<tr style="border-bottom:1px solid #E5E8EC;">\n            <td style="padding:10px 8px;font-weight:700;color:#101825;">{r[\'score\']}</td>\n            <td style="padding:10px 8px;font-weight:600;">\n                <a href="https://finance.yahoo.com/quote/{r[\'ticker\']}" style="color:#1FAE96; text-decoration:none;">{r[\'ticker\']}</a>\n            </td>\n            <td style="padding:10px 8px;color:#5B6472;">{r[\'flip_date\']}</td>\n            <td style="padding:10px 8px;color:#5B6472;">{r[\'dagen_geleden\']}d ago</td>\n            <td style="padding:10px 8px;color:#5B6472;">{r[\'prijs_bij_omslag\']} &rarr; {r[\'prijs_nu\']}</td>\n            <td style="padding:10px 8px;font-weight:600;color:{\'#0F8F6E\' if r[\'sinds_omslag_pct\'] >= 0 else \'#C1524A\'};">{r[\'sinds_omslag_pct\']:+.2f}%</td>\n        </tr>"""\n        for _, r in df_hits.iterrows()\n    )\n\n    macro_line_html = (\n        f\'<p style="margin-top:8px; font-size:13px; color:#1FAE96; font-weight:600;">\xf0\x9f\x93\x85 {macro_teaser}</p>\'\n        if macro_teaser else ""\n    )\n\n    html_body = f"""\n    <div style="font-family: -apple-system, \'Segoe UI\', Roboto, Arial, sans-serif; max-width: 600px; margin: 0 auto; background:#ffffff;">\n        <div style="background:#101825; padding: 28px 24px; border-radius: 12px 12px 0 0;">\n            <div style="color:#1FAE96; font-size:13px; font-weight:600; letter-spacing:1px; text-transform:uppercase;">Hesty\'s Daily</div>\n            <div style="color:#EAEDF1; font-size:22px; font-weight:700; margin-top:4px;">{greeting}</div>\n        </div>\n        <div style="padding: 24px; border: 1px solid #E5E8EC; border-top: none; border-radius: 0 0 12px 12px;">\n            <p style="font-size:15px; color:#101825; line-height:1.5; margin-top:0;">{intro_line}</p>\n            {macro_line_html}\n            <table style="width:100%; border-collapse:collapse; margin-top:16px;">\n                <tr style="border-bottom:2px solid #101825;">\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Score</th>\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Ticker</th>\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Flip Date</th>\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Since</th>\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Price</th>\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Change</th>\n                </tr>\n                {rows_html}\n            </table>\n            <p style="margin-top:20px; font-size:14px; color:#5B6472; line-height:1.5;">\n                Want sector/theme rotation and earnings surprises too? Check\n                <a href="https://hestys.streamlit.app/discover" style="color:#1FAE96; font-weight:600; text-decoration:none;">Discover</a> on the site,\n                or see <a href="https://hestys.streamlit.app/today" style="color:#1FAE96; font-weight:600; text-decoration:none;">Today</a>\n                for macro events and yesterday\'s biggest movers.\n            </p>\n            <p style="margin-top:24px; font-size:14px; color:#101825; font-weight:600;">&mdash; Hesty\'s, your personal investment assistant</p>\n            <p style="margin-top:16px; font-size:12px; color:#9AA1AC; font-style:italic;">This is a screener, not investment advice.</p>\n        </div>\n    </div>\n    """\n    return text_body, html_body\n\n\ndef main(send_own_email: bool = True) -> None:\n    tickers = build_ticker_list()\n\n    print("Fetching benchmark returns (for relative strength)...")\n    benchmark_returns = fetch_benchmark_returns_daily()\n\n    print(f"\\nScreening {len(tickers)} tickers for recent bullish Supertrend flips "\n          f"(daily, ATR length {ATR_LENGTH}, multiplier {ATR_MULTIPLIER})...\\n")\n\n    hits = []\n    movers = []\n    for ticker in tickers:\n        try:\n            df = fetch_daily(ticker)\n        except Exception as exc:\n            print(f"  {ticker}: fout bij ophalen ({exc})")\n            continue\n\n        # Dag-op-dag-verandering, voor \'top movers\' -- hergebruikt dezelfde\n        # opgehaalde data als de signaal-check hieronder, dus GEEN extra\n        # API-aanroepen nodig.\n        if not df.empty and len(df) >= 2:\n            try:\n                day_change = (df["close"].iloc[-1] / df["close"].iloc[-2] - 1) * 100\n                movers.append({"ticker": ticker, "change_pct": round(day_change, 2)})\n            except Exception:\n                pass\n\n        result = check_ticker_daily(ticker, benchmark_returns, df=df)\n        if result:\n            hits.append(result)\n            print(f"  {ticker}: SIGNAL ({result[\'dagen_geleden\']} day(s) ago, score {result[\'score\']})")\n        else:\n            print(f"  {ticker}: no recent signal")\n\n    if movers:\n        df_movers = pd.DataFrame(movers).sort_values("change_pct", ascending=False)\n        df_movers.to_csv("top_movers.csv", index=False)\n        print(f"\\nSaved {len(df_movers)} tickers\' daily change to \'top_movers.csv\'.")\n\n    if not hits:\n        print("\\nNo signals today.")\n        if send_own_email and email_is_configured():\n            send_email(subject="Daily screener: no signals today", body_text="No signals found today.")\n        return\n\n    df_hits = pd.DataFrame(hits)\n    df_hits.sort_values("score", ascending=False, inplace=True)\n\n    print(f"\\n=== {len(hits)} SIGNALS FOUND ===\\n")\n    print(df_hits.to_string(index=False))\n\n    df_hits.to_csv("supertrend_signals_daily.csv", index=False)\n    print("\\nSaved to \'supertrend_signals_daily.csv\'.")\n\n    if send_own_email and email_is_configured():\n        text_body, html_body = build_email_body_daily(df_hits)\n        send_email(subject=f"Daily screener: {len(hits)} new signals", body_text=text_body, body_html=html_body)\n\n\nif __name__ == "__main__":\n    main()\n'

